// Builds src/features/_registry/nav.generated.ts from every src/features/<domain>/nav.ts.
// The output is gitignored, so adding a domain never edits a shared file.
import { existsSync, mkdirSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..', 'src', 'features');
const domains = readdirSync(root, { withFileTypes: true })
  .filter(
    (d) => d.isDirectory() && !d.name.startsWith('_') && existsSync(join(root, d.name, 'nav.ts')),
  )
  .map((d) => d.name)
  .sort();

const lines = [
  '// GENERATED by scripts/gen-registry.mjs. Do not edit; do not commit.',
  "import type { NavItem } from './types';",
  ...domains.map((d, i) => `import { nav as n${i} } from '../${d}/nav';`),
  `export const NAV: NavItem[] = [${domains.map((_, i) => `...n${i}`).join(', ')}];`,
  '',
];
mkdirSync(join(root, '_registry'), { recursive: true });
writeFileSync(join(root, '_registry', 'nav.generated.ts'), lines.join('\n'));
console.log(`nav registry: ${domains.length} domain(s)`);
